<?php $this->assign('title', 'Usuarios | CatOps Admin'); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><h1 class="h2 mb-1">Usuarios</h1><p class="text-muted mb-0"><?= (int)$pagination['total'] ?> resultados.</p></div></div>
<section class="card admin-card mb-4"><div class="card-body">
  <form class="row g-2" method="get"><div class="col-12 col-md-5"><input class="form-control" name="q" value="<?= h($filters['q']) ?>" placeholder="Nombre o correo"></div><div class="col-6 col-md-2"><select class="form-select" name="verified"><option value="">Verificación</option><option value="1" <?= $filters['verified'] === '1' ? 'selected' : '' ?>>Verificado</option><option value="0" <?= $filters['verified'] === '0' ? 'selected' : '' ?>>Pendiente</option></select></div><div class="col-6 col-md-2"><select class="form-select" name="role"><option value="">Rol</option><?php foreach (['user' => 'Usuario', 'admin' => 'Admin', 'superadmin' => 'Superadmin'] as $value => $label): ?><option value="<?= $value ?>" <?= $filters['role'] === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="col-6 col-md-2"><select class="form-select" name="subscription"><option value="">Suscripción</option><?php foreach (['active', 'expiring', 'grace_period', 'expired', 'suspended', 'cancelled'] as $status): ?><option value="<?= $status ?>" <?= $filters['subscription'] === $status ? 'selected' : '' ?>><?= h($status) ?></option><?php endforeach; ?></select></div><div class="col-6 col-md-1"><button class="btn btn-primary w-100">Buscar</button></div></form>
</div></section>
<section class="card admin-card"><div class="table-wrap"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Verificación</th><th>Registro</th><th></th></tr></thead><tbody><?php foreach ($pagination['items'] as $user): ?><tr><td><strong><?= h($user->name) ?></strong><small class="d-block text-muted"><?= h($user->email) ?></small></td><td><?= h($user->role === 'customer' ? 'user' : $user->role) ?></td><td><span class="badge text-bg-<?= $user->active ? 'success' : 'secondary' ?> badge-status"><?= $user->active ? 'activo' : 'bloqueado' ?></span></td><td><?= $user->email_verified ? 'Sí' : 'No' ?></td><td><?= h($user->created) ?></td><td><a class="btn btn-sm btn-outline-primary" href="/admin/users/<?= (int)$user->id ?>">Ver</a></td></tr><?php endforeach; ?></tbody></table></div><div class="card-body"><?= $this->element('admin_pagination', compact('pagination')) ?></div></section>
